const supplierConsultations = `-- name: SupplierConsultations :many
SELECT r.id AS rfq_id, r.number, r.title, r.status, r.response_deadline, r.published_at,
       p.id AS project_id, p.name AS project_name, rs.created_at AS consulted_at,
       (SELECT count(*) FROM rfq_offers o WHERE o.rfq_supplier_id = rs.id)::int AS offer_count,
       last.total_amount AS last_offer_total, last.submitted_at AS last_offer_at
  FROM rfq_suppliers rs
  JOIN rfqs r     ON r.id = rs.rfq_id
  JOIN projects p ON p.id = r.project_id
  LEFT JOIN rfq_offers last ON last.rfq_supplier_id = rs.id
   AND last.version = (SELECT max(x.version) FROM rfq_offers x WHERE x.rfq_supplier_id = rs.id)
 WHERE rs.organization_id = $1 AND rs.supplier_id = $2
   AND ($3::boolean
        OR p.manager_id = $4
        OR EXISTS (SELECT 1 FROM project_members m WHERE m.project_id = p.id AND m.user_id = $4))
 ORDER BY rs.created_at DESC
 LIMIT 100
`

type SupplierConsultationsParams struct {
	OrgID       uuid.UUID `json:"org_id"`
	SupplierID  uuid.UUID `json:"supplier_id"`
	AllProjects bool      `json:"all_projects"`
	UserID      uuid.UUID `json:"user_id"`
}

type SupplierConsultationsRow struct {
	RfqID            uuid.UUID   `json:"rfq_id"`
	Number           int32       `json:"number"`
	Title            string      `json:"title"`
	Status           string      `json:"status"`
	ResponseDeadline *civil.Date `json:"response_deadline"`
	PublishedAt      *time.Time  `json:"published_at"`
	ProjectID        uuid.UUID   `json:"project_id"`
	ProjectName      string      `json:"project_name"`
	ConsultedAt      time.Time   `json:"consulted_at"`
	OfferCount       int32       `json:"offer_count"`
	LastOfferTotal   *int64      `json:"last_offer_total"`
	LastOfferAt      *time.Time  `json:"last_offer_at"`
}

// Demandes de prix où le fournisseur a été consulté, limitées aux chantiers visibles par l'acteur.
func (q *Queries) SupplierConsultations(ctx context.Context, arg SupplierConsultationsParams) ([]SupplierConsultationsRow, error) {
	rows, err := q.db.Query(ctx, supplierConsultations,
		arg.OrgID,
		arg.SupplierID,
		arg.AllProjects,
		arg.UserID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SupplierConsultationsRow{}
	for rows.Next() {
		var i SupplierConsultationsRow
		if err := rows.Scan(
			&i.RfqID,
			&i.Number,
			&i.Title,
			&i.Status,
			&i.ResponseDeadline,
			&i.PublishedAt,
			&i.ProjectID,
			&i.ProjectName,
			&i.ConsultedAt,
			&i.OfferCount,
			&i.LastOfferTotal,
			&i.LastOfferAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

