const supplierPurchaseTotals = `-- name: SupplierPurchaseTotals :one
SELECT count(*)::int AS purchase_count,
       COALESCE(sum(e.amount) FILTER (WHERE e.status = 'approved'), 0)::bigint AS approved_amount,
       COALESCE(sum(e.amount_paid), 0)::bigint AS paid_amount
  FROM expenses e
  JOIN projects p ON p.id = e.project_id
 WHERE e.organization_id = $1 AND e.supplier_id = $2 AND e.status <> 'cancelled'
   AND ($3::boolean
        OR p.manager_id = $4
        OR EXISTS (SELECT 1 FROM project_members m WHERE m.project_id = p.id AND m.user_id = $4))
`

